# Group CFA (Invariance). Options, results and panel: jamovi/groupCfa.*.yaml
# (generated by tools/gen_yaml.py); jmvtools generates R/groupCfa.h.R.
# All of the work is in R/jmv-invariance.R.

groupCfaClass <- if (requireNamespace("jmvcore", quietly = TRUE)) R6::R6Class(
  "groupCfaClass",
  inherit = groupCfaBase,
  private = list(
    .factors = function() psw_jmv_factors(self$options$factors),
    .init = function() psw_jmv_inv_init(self, private$.factors()),
    .run = function() psw_jmv_inv_run(self, private$.factors()),
    .diagram = function(image, ...) psw_jmv_diagram(image)
  )
)
